// Shape-accurate miniature of Sphinx's searchindex.js: a JSONP-style call
// wrapping docnames, titles, and a term -> document-index map. Platform
// detection keys off the presence of this file, so it is here for detection
// tests rather than because anything reads its contents yet.
Search.setIndex({
  docnames: ["index", "api/reference", "guide/index"],
  titles: ["Widget", "API reference", "User guide"],
  filenames: ["index.rst", "api/reference.rst", "guide/index.rst"],
  terms: { widget: [0, 1], resize: [1], install: [0], guide: [2] },
  objects: { "widget.Widget": [[1, "widget.Widget", "widget.Widget"]] },
});
